import React from 'react';

interface Props {
  initialRadius: number;
    maxRadius: number;
      onRadiusChange: (radius: number) => void;
        onConfirm: (radius: number) => void;
          onCancel: () => void;
          }

          export const RoundedCornerDialog: React.FC<Props> = ({
            initialRadius,
              maxRadius,
                onRadiusChange,
                  onConfirm,
                    onCancel,
                    }) => {
                      const [radius, setRadius] = React.useState(initialRadius);
                        const [inputStr, setInputStr] = React.useState(initialRadius.toFixed(2));

                          React.useEffect(() => {
                              setRadius(initialRadius);
                                  setInputStr(initialRadius.toFixed(2));
                                    }, [initialRadius]);

                                      const commitRadius = (v: number) => {
                                          const clamped = Math.max(0.05, Math.min(maxRadius, v));
                                              setRadius(clamped);
                                                  setInputStr(clamped.toFixed(2));
                                                      onRadiusChange(clamped);
                                                        };

                                                          const handleSliderChange = (e: React.ChangeEvent<HTMLInputElement>) => {
                                                              commitRadius(parseFloat(e.target.value));
                                                                };

                                                                  const handleInputBlur = () => {
                                                                      const v = parseFloat(inputStr.replace(',', '.'));
                                                                          if (!isNaN(v)) commitRadius(v);
                                                                              else setInputStr(radius.toFixed(2));
                                                                                };

                                                                                  return (
                                                                                      <>
                                                                                            <div
                                                                                                    onClick={onCancel}
                                                                                                            style={{
                                                                                                                      position: 'fixed',
                                                                                                                                inset: 0,
                                                                                                                                          background: 'rgba(0,0,0,0.5)',
                                                                                                                                                    zIndex: 9999,
                                                                                                                                                            }}
                                                                                                                                                                  />
                                                                                                                                                                        <div
                                                                                                                                                                                onClick={(e) => e.stopPropagation()}
                                                                                                                                                                                        style={{
                                                                                                                                                                                                  position: 'fixed',
                                                                                                                                                                                                            top: '50%',
                                                                                                                                                                                                                      left: '50%',
                                                                                                                                                                                                                                transform: 'translate(-50%, -50%)',
                                                                                                                                                                                                                                          background: '#fff',
                                                                                                                                                                                                                                                    borderRadius: 16,
                                                                                                                                                                                                                                                              padding: 24,
                                                                                                                                                                                                                                                                        maxWidth: 380,
                                                                                                                                                                                                                                                                                  width: '90%',
                                                                                                                                                                                                                                                                                            zIndex: 10000,
                                                                                                                                                                                                                                                                                                      boxShadow: '0 8px 32px rgba(0,0,0,0.3)',
                                                                                                                                                                                                                                                                                                                direction: 'rtl',
                                                                                                                                                                                                                                                                                                                        }}
                                                                                                                                                                                                                                                                                                                              >
                                                                                                                                                                                                                                                                                                                                      <h3 style={{ margin: '0 0 8px 0', color: '#003366', fontSize: 17, textAlign: 'center' }}>
                                                                                                                                                                                                                                                                                                                                                🔘 تقويس الركن
                                                                                                                                                                                                                                                                                                                                                        </h3>
                                                                                                                                                                                                                                                                                                                                                                <p style={{ margin: '0 0 16px 0', color: '#666', fontSize: 13, textAlign: 'center' }}>
                                                                                                                                                                                                                                                                                                                                                                          اضبط قطر القوس — المعاينة المباشرة تظهر على المسقط
                                                                                                                                                                                                                                                                                                                                                                                  </p>

                                                                                                                                                                                                                                                                                                                                                                                          <div style={{ marginBottom: 16 }}>
                                                                                                                                                                                                                                                                                                                                                                                                    <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 8 }}>
                                                                                                                                                                                                                                                                                                                                                                                                                <span style={{ fontSize: 13, fontWeight: 700, color: '#333' }}>قطر القوس</span>
                                                                                                                                                                                                                                                                                                                                                                                                                            <span style={{ fontSize: 13, fontWeight: 700, color: '#00509e' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                          {(radius * 100).toFixed(0)} سم
                                                                                                                                                                                                                                                                                                                                                                                                                                                      </span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <input
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      type="range"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  min={0.05}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              max={maxRadius}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          step={0.01}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      value={radius}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  onChange={handleSliderChange}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              style={{ width: '100%' }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div style={{ marginBottom: 20 }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <label style={{ fontSize: 13, fontWeight: 700, color: '#333', display: 'block', marginBottom: 6 }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              أو أدخل القيمة يدوياً (م)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <input
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              type="text"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          inputMode="decimal"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      dir="ltr"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  value={inputStr}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              onChange={(e) => setInputStr(e.target.value)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          onFocus={(e) => e.target.select()}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      onBlur={handleInputBlur}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  onKeyDown={(e) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (e.key === 'Enter') (e.target as HTMLInputElement).blur();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        style={{
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      width: '100%',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    padding: 10,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  borderRadius: 8,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                border: '2px solid #00509e',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              fontSize: 15,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            textAlign: 'center',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          boxSizing: 'border-box',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div style={{ display: 'flex', gap: 10 }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      onClick={() => onConfirm(radius)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  style={{
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                flex: 1,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              padding: 12,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            borderRadius: 10,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          border: 'none',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        background: '#00509e',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      color: '#fff',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    fontWeight: 700,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  fontSize: 15,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                cursor: 'pointer',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ✅ تأكيد
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  onClick={onCancel}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              style={{
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            flex: 1,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          padding: 12,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        borderRadius: 10,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      border: '2px solid #ccc',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    background: '#f0f0f0',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  color: '#333',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                fontWeight: 700,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              fontSize: 15,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            cursor: 'pointer',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ✖ إلغاء
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            };